// ===================================================================================
// Project:   Ethernet Cable Tester - RJ45 Line Driver
// Class:     CPins
// ===================================================================================
//
// Drives the eight RJ45 line pins. Each pin can be:
//
//   MODE_LOW   - logic zero  (displayed as inverted T)
//   MODE_HIGH  - logic one   (displayed as '+')
//   MODE_PWM   - software PWM carrier (displayed as sine wave '~')
//
// The PWM is generated by the TIM2 update interrupt: 1 kHz carrier, 50 duty
// steps (2% resolution). The interrupt runs only while at least one pin is
// in MODE_PWM, otherwise the timer is stopped.
//
// In REC mode all pins are switched to high impedance inputs and their
// levels can be read with readLevels() (bit 7..0 = contact 8..1, display
// order left to right is contact 1..8).
//
// ===================================================================================
#pragma once

#include <stdint.h>

class CPins {
public:
  static const uint8_t COUNT      = 8;               // RJ45 contacts
  static const uint8_t MODE_LOW   = 0;               // drive '0'
  static const uint8_t MODE_HIGH  = 1;               // drive '1'
  static const uint8_t MODE_PWM   = 2;               // drive PWM

  static void    begin();                             // all pins -> Hi-Z inputs
  static void    toInputs();                          // all pins -> Hi-Z inputs
  static void    apply(const uint8_t* modes);         // drive pins per mode array
  static uint8_t readLevels();                        // sampled input levels, bit0 = contact 1

  static void    setDuty(uint8_t percent);            // PWM duty 0..100 [%]

  // Called from TIM2_IRQHandler only:
  static void    irqTick();
};
